describe(
  "umbrella gate 3 — test (per test-strategy.md \u00a71 P13; first end-to-end test gate for science-advantage)",
  () => {
    beforeAll(() => {
      const result = runGate(GATE_ARGS.test);
      testOutput = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
      testStatus = result.status;
    }, 600_000);

    it("pnpm --filter science-advantage exec vitest run --config vitest.unit.config.ts completed", () => {
      expect(
        testStatus,
        `Expected pnpm --filter science-advantage exec vitest run ` +
          `--config vitest.unit.config.ts to exit; got status ` +
          `${String(testStatus)}. First 1 KB of output:\n` +
          `${testOutput.slice(0, 1024)}`,
      ).not.toBeNull();
    });

    it("pnpm --filter science-advantage exec vitest run --config vitest.unit.config.ts exits 0", () => {
      // The Phase 13 umbrella gate for `test`. This is the
      // first end-to-end test gate for the science-advantage
      // package at the track level. We use the DB-free
      // unit-test config (`vitest.unit.config.ts`) per
      // `test-strategy.md` §2 to avoid the
      // `science_advantage_test` DB requirement. Per
      // `turbo.json:18-20`, the `test` task declares
      // `dependsOn: ["^build"]` so the workspace deps must
      // build first, which adds non-trivial time to the gate
      // (the workspace-deps build is parallel via turbo's task
      // graph).
      //
      // Red-phase: may fail today if any of Phases 0–12
      // introduced a unit-test regression, OR if the
      // workspace-deps build is broken. Passes if Phases 0–12
      // left the unit-test suite green.
      expect(
        testStatus,
        `Expected pnpm --filter science-advantage exec vitest run ` +
          `--config vitest.unit.config.ts to exit 0 (the Phase 13 ` +
          `umbrella gate for test per test-strategy.md \u00a71 P13). ` +
          `Currently exits with code ${String(testStatus)}. The ` +
          `\`test\` task in turbo.json:18-20 declares ` +
          `\`dependsOn: ["^build"]\` so the workspace deps must ` +
          `build first; a non-zero exit may indicate either a ` +
          `unit-test regression in science-advantage OR a ` +
          `workspace-deps build failure. First 4 KB of output:\n` +
          `${testOutput.slice(0, 4096)}`,
      ).toBe(0);
    });
  },
);

